require __DIR__.'/app/bootstrap.php'; require __DIR__.'/app/layout.php'; $admin=require_permission('manage_users'); $id=(int)($_GET['id']??$_POST['id']??0);$q=db()->prepare('SELECT id,full_name,username FROM users WHERE id=?');$q->execute([$id]);$target=$q->fetch();if(!$target){http_response_code(404);exit('User not found.');}$temporary='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$temporary=strtoupper(bin2hex(random_bytes(5)));db()->prepare('UPDATE users SET password_hash=?,must_change_password=1 WHERE id=?')->execute([password_hash($temporary,PASSWORD_DEFAULT),$id]);audit_admin_action((int)$admin['id'],'user_password_reset','user',$id);}
page_start('Reset password',$admin);?><div class="account-action-screen"><section class="account-action-panel"><span class="account-action-icon" aria-hidden="true">•••</span><h2>Reset <?=e($target['full_name'])?>’s password</h2><p class="muted">Username: <?=e($target['username'])?></p><?php if($temporary):?><div class="temporary-password"><span>Temporary password</span><code><?=e($temporary)?></code></div><p>The user must change this password at their next sign-in.</p><a class="button" href="admin.php">Return to Roles &amp; Access</a><?php else:?><p>Generate a one-time password for this user. Their current password will stop working immediately.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="record-form-actions"><a class="button button-secondary" href="admin.php">Cancel</a><button class="button">Generate password</button></div></form><?php endif;?></section></div><?php page_end();
